-- ============================================================
-- i18n — CAMPO `component` de equipment_error_codes (en/es/fr)
-- ------------------------------------------------------------
-- Traducoes por glossario HVAC composicional (frases nominais de componente:
-- "Sensor de descarga", "Placa externa (EEPROM)", "Rede elétrica / placa externa").
-- Siglas mantidas: IPM, IGBT, EEPROM, PCB, PFC, EEV, EXV, DC, T1..T4, TP, Td...
-- Merge no jsonb existente (nao sobrescreve outros campos ja traduzidos).
-- Match por valor base pt-br do campo `component`. Idempotente.
-- ============================================================
-- component i18n (compositional HVAC glossary)
UPDATE public.equipment_error_codes t SET i18n = COALESCE(t.i18n,'{}'::jsonb)
  || jsonb_build_object('en', COALESCE(t.i18n->'en','{}'::jsonb) || v.en,
                       'es', COALESCE(t.i18n->'es','{}'::jsonb) || v.es,
                       'fr', COALESCE(t.i18n->'fr','{}'::jsonb) || v.fr)
FROM (VALUES
  ('Alimentação', '{"component": "power supply"}'::jsonb, '{"component": "alimentación"}'::jsonb, '{"component": "alimentation"}'::jsonb),
