UPDATE public.equipment_error_codes t SET i18n = COALESCE(t.i18n,'{}'::jsonb)
  || jsonb_build_object('en', COALESCE(t.i18n->'en','{}'::jsonb) || v.en,
                       'es', COALESCE(t.i18n->'es','{}'::jsonb) || v.es,
                       'fr', COALESCE(t.i18n->'fr','{}'::jsonb) || v.fr)
FROM (VALUES
  ('Termistor de sucção', '{"component": "suction thermistor"}'::jsonb, '{"component": "termistor de succión"}'::jsonb, '{"component": "thermistance d’aspiration"}'::jsonb),
  ('Termistor externo', '{"component": "outdoor thermistor"}'::jsonb, '{"component": "termistor exterior"}'::jsonb, '{"component": "thermistance extérieure"}'::jsonb),
  ('Termistor IPT', '{"component": "thermistor IPT"}'::jsonb, '{"component": "termistor IPT"}'::jsonb, '{"component": "thermistance IPT"}'::jsonb),
  ('Termistor IRT', '{"component": "thermistor IRT"}'::jsonb, '{"component": "termistor IRT"}'::jsonb, '{"component": "thermistance IRT"}'::jsonb),
  ('Termistor OPT', '{"component": "thermistor OPT"}'::jsonb, '{"component": "termistor OPT"}'::jsonb, '{"component": "thermistance OPT"}'::jsonb),
  ('Termostato do compressor', '{"component": "compressor thermostat"}'::jsonb, '{"component": "termostato del compresor"}'::jsonb, '{"component": "thermostat du compresseur"}'::jsonb),
  ('Trocador de calor (externa) / sensor', '{"component": "heat exchanger (outdoor) / sensor"}'::jsonb, '{"component": "intercambiador de calor (exterior) / sensor"}'::jsonb, '{"component": "échangeur de chaleur (extérieure) / sonde"}'::jsonb),
  ('Unidade externa', '{"component": "outdoor unit"}'::jsonb, '{"component": "unidad exterior"}'::jsonb, '{"component": "unité extérieure"}'::jsonb),
  ('Unidade externa / sensor externo', '{"component": "outdoor unit / outdoor sensor"}'::jsonb, '{"component": "unidad exterior / sensor exterior"}'::jsonb, '{"component": "unité extérieure / sonde extérieure"}'::jsonb),
  ('Válvula 4 vias / bobina / PCB', '{"component": "4-way valve / coil / PCB"}'::jsonb, '{"component": "válvula de 4 vías / bobina / PCB"}'::jsonb, '{"component": "vanne 4 voies / bobine / PCB"}'::jsonb),
  ('Ventilador externo', '{"component": "outdoor fan"}'::jsonb, '{"component": "ventilador exterior"}'::jsonb, '{"component": "ventilateur extérieur"}'::jsonb),
  ('Ventilador externo / sensor', '{"component": "outdoor fan / sensor"}'::jsonb, '{"component": "ventilador exterior / sensor"}'::jsonb, '{"component": "ventilateur extérieur / sonde"}'::jsonb),
  ('Ventilador interno', '{"component": "indoor fan"}'::jsonb, '{"component": "ventilador interior"}'::jsonb, '{"component": "ventilateur intérieur"}'::jsonb),
  ('Ventilador interno (CC)', '{"component": "indoor fan (CC)"}'::jsonb, '{"component": "ventilador interior (CC)"}'::jsonb, '{"component": "ventilateur intérieur (CC)"}'::jsonb)
